SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(480, 270, "#81d4fa");
  SZGame2D.setStageDescription("Corra com o dino e pule os cactos apertando espaço");
  const dino = SZGame2D.createDino({ x: 110, y: 150, size: 64, color: "#8b5cf6" });
  // Quando acontecer
  SZGame2D.onJump(() => dino, () => {
      SZGame2D.playFx("jump");
    }, "dino-ref-19");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawForest(ctx, 5);
    SZGame2D.applyGravity(dino);
    SZGame2D.controlDino(dino, ctx, 14);
    SZGame2D.drawSprite(ctx, dino);
  }, "dino-ref-10");
}, "__sz-project");
